<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $from = \Carbon\Carbon::parse("2026-09-21")->startOfDay(); $res = DB::table("stock_movements")->select("item_id", DB::raw("SUM(qty_in) - SUM(qty_out) as net_qty"))->where("moved_at", "<", $from)->groupBy("item_id")->pluck("net_qty", "item_id"); print_r($res);
